// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    W_WALLET c;

    function setUp() public {
        c = new W_WALLET(address(new Log()));
    }

    function testFuzz_property(uint256 actorSeed, uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        address actor = address(uint160(uint256(keccak256(abi.encodePacked(actorSeed)))));
        vm.assume(actor != address(0));
        amount = bound(amount, 1 ether, 10 ether);

        vm.deal(actor, amount);

        vm.prank(actor);
        c.Put{value: amount}(0);

        vm.warp(block.timestamp + 1);

        (uint256 unlockTime, uint256 balanceBefore) = c.Acc(actor);
        vm.assume(balanceBefore >= c.MinSum());

        vm.prank(actor);
        c.Collect(amount);

        (, uint256 balanceAfter) = c.Acc(actor);

        assertTrue(balanceAfter == balanceBefore - amount);
    }
}
